sysauto_script.script:
(function() {
    var now = new GlideDateTime();
    gs.info('TrackMed: Starting daily dose log generation at ' + now.getDisplayValue());

    // Query all active medication schedules
    var schedGr = new GlideRecord('x_snc_trackmed_medication_schedule_table');
    schedGr.addQuery('state', 'active');
    schedGr.query();

    var totalCreated = 0;

    while (schedGr.next()) {
        var frequency = schedGr.getValue('frequency');
        var patient = schedGr.getValue('patient');
        var caretaker = schedGr.getValue('caretaker');
        var schedSysId = schedGr.getUniqueValue();
        var medName = schedGr.getValue('medication_name');

        // Create Morning dose (all frequencies)
        _createDoseLog(patient, caretaker, schedSysId, 'Medication dose - Morning (' + medName + ')');
        totalCreated++;

        // Create Afternoon dose (twice_Daily or thrice_Daily)
        if (frequency == 'twice_Daily' || frequency == 'thrice_Daily') {
            _createDoseLog(patient, caretaker, schedSysId, 'Medication dose - Afternoon (' + medName + ')');
            totalCreated++;
        }

        // Create Evening dose (thrice_Daily only)
        if (frequency == 'thrice_Daily') {
            _createDoseLog(patient, caretaker, schedSysId, 'Medication dose - Evening (' + medName + ')');
            totalCreated++;
        }
    }

    gs.info('TrackMed: Daily dose log generation complete. Created ' + totalCreated + ' dose logs.');

    function _createDoseLog(patient, caretaker, medication, description) {
        var doseGr = new GlideRecord('x_snc_trackmed_dose_log');
        doseGr.initialize();
        doseGr.setValue('patient', patient);
        doseGr.setValue('care_taker', caretaker);
        doseGr.setValue('medication', medication);
        doseGr.setValue('status', 'Scheduled');
        doseGr.setValue('short_description', description);
        doseGr.insert();
    }
})();
